#!/usr/bin/env python3
"""Generate the validated Aurelia CHW Project Control Postman collection.

The embedded payload is zlib-compressed JSON so the source stays small while the
emitted artifact remains a normal Postman Collection v2.1 JSON file.
"""

from __future__ import annotations

import base64
import json
import zlib
from pathlib import Path

OUTPUT = Path(__file__).with_name("Project-Control-CHW-Demo.postman_collection.json")

COMPRESSED_COLLECTION = """"""


def main() -> None:
    raw = zlib.decompress(base64.b64decode(COMPRESSED_COLLECTION)).decode("utf-8")
    data = json.loads(raw)

    # Guard the two dynamic handoffs that are easy to break when editing the collection.
    requests = {
        request["name"]: request
        for folder in data["item"]
        for request in folder.get("item", [])
    }
    assert "followUpDecisionId" in json.dumps(requests["26. Accept remaining 20 m"])
    assert "followUpMeasurementId" in json.dumps(requests["29. Create second immutable measurement"])
    assert "16. FINAL PROOF - Payment reverse trace" in requests

    OUTPUT.write_text(json.dumps(data, indent=2) + "\n", encoding="utf-8")
    print(f"Generated {OUTPUT}")
    print(f"Folders: {len(data['item'])}; requests: {sum(len(f.get('item', [])) for f in data['item'])}")


if __name__ == "__main__":
    main()
